mapper.select:
SELECT t1.CORP_GR AS corp_gr , t1.FUND_CD AS fund_cd , t1.FUND_NM AS fund_nm , t1.FUND_NM AS xx_fund_cd , t1.TYPE_GB AS type_gb , t1.FUND_CURRENCY AS fund_currency , '0' AS fund_select , TO_CHAR(t1.HAEJI_YMD, 'YYYY-MM-DD') AS haeji_ymd FROM SZM0IA t1 WHERE t1.CORP_GR = #{corpGr} AND t1.FUND_CD IN ( SELECT ta.FUND_CD FROM SKT0BU ta WHERE ta.CORP_GR = #{corpGr} AND ta.TR_YMD = TO_DATE(REPLACE(REPLACE(#{ymd}, '-', ''), '.', ''), 'YYYYMMDD')
AND ta.PROC_STEP = '9'
) ORDER BY t1.FUND_CD
